import json
import xml.etree.ElementTree as ET

_FIELDS = ("sender", "topic", "message")


def _media_type(value):
    if not isinstance(value, str):
        raise TypeError("media_type must be a string")
    return value.strip().lower()


def _validate(data):
    if not isinstance(data, dict):
        raise TypeError("packet must be a dictionary")
    if set(data) != set(_FIELDS):
        raise ValueError("packet fields are invalid")
    if any(not isinstance(data[name], str) for name in _FIELDS):
        raise TypeError("packet values must be strings")
    return {name: data[name] for name in _FIELDS}


def decode_packet(body, media_type):
    kind = _media_type(media_type)
    if isinstance(body, bytes):
        try:
            body = body.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ValueError("body is not UTF-8") from exc
    elif not isinstance(body, str):
        raise TypeError("body must be text or bytes")
    if not body.strip():
        raise ValueError("body is empty")

    if kind == "application/vnd.packet+json":
        try:
            return _validate(json.loads(body))
        except json.JSONDecodeError as exc:
            raise ValueError("malformed JSON") from exc
    if kind == "application/vnd.packet+xml":
        try:
            root = ET.fromstring(body)
        except ET.ParseError as exc:
            raise ValueError("malformed XML") from exc
        children = list(root)
        if root.tag != "packet" or len(children) != len(_FIELDS):
            raise ValueError("invalid XML packet")
        if [child.tag for child in children] != list(_FIELDS):
            raise ValueError("invalid XML fields")
        if any(list(child) for child in children):
            raise ValueError("packet fields cannot be nested")
        return _validate({child.tag: child.text or "" for child in children})
    raise ValueError("unsupported media type")


def encode_packet(data, media_type):
    packet = _validate(data)
    kind = _media_type(media_type)
    if kind == "application/vnd.packet+json":
        return json.dumps(packet, separators=(",", ":"), ensure_ascii=False)
    if kind == "application/vnd.packet+xml":
        root = ET.Element("packet")
        for name in _FIELDS:
            ET.SubElement(root, name).text = packet[name]
        return ET.tostring(root, encoding="unicode", short_empty_elements=True)
    raise ValueError("unsupported media type")
